  1→package jlsm.sstable;
  2→
  3→import jlsm.bloom.blocked.BlockedBloomFilter;
  4→import jlsm.core.compression.CompressionCodec;
  5→import jlsm.core.model.Entry;
  6→import jlsm.core.model.Level;
  7→import jlsm.core.model.SequenceNumber;
  8→import org.junit.jupiter.api.Test;
  9→import org.junit.jupiter.api.io.TempDir;
 10→
 11→import java.io.IOException;
 12→import java.lang.foreign.MemorySegment;
 13→import java.nio.file.Files;
 14→import java.nio.file.Path;
 15→import java.util.ArrayList;
 16→import java.util.Iterator;
 17→import java.util.List;
 18→import java.util.Optional;
 19→import java.util.Random;
 20→
 21→import static org.junit.jupiter.api.Assertions.*;
 22→
 23→/**
 24→ * Tests for SSTable v2 format with block-level compression.
 25→ *
 26→ * <p>
 27→ * Covers the TrieSSTableWriter and TrieSSTableReader extensions for compression,
 28→ * backward compatibility with v1 files, and the CompressionCodec integration.
 29→ */
 30→class SSTableCompressionTest {
 31→
 32→    private static MemorySegment seg(String s) {
 33→        return MemorySegment.ofArray(s.getBytes());
 34→    }
 35→
 36→    private static Entry.Put put(String key, String value, long seq) {
 37→        return new Entry.Put(seg(key), seg(value), new SequenceNumber(seq));
 38→    }
 39→
 40→    private static Entry.Delete del(String key, long seq) {
 41→        return new Entry.Delete(seg(key), new SequenceNumber(seq));
 42→    }
 43→
 44→    /**
 45→     * Writes a v1 SSTable (no compression) using the original constructor.
 46→     */
 47→    private Path writeV1SSTable(Path dir, String name, List<Entry> entries) throws IOException {
 48→        Path path = dir.resolve(name);
 49→        try (TrieSSTableWriter w = new TrieSSTableWriter(1L, Level.L0, path)) {
 50→            for (Entry e : entries) {
 51→                w.append(e);
 52→            }
 53→            w.finish();
 54→        }
 55→        return path;
 56→    }
 57→
 58→    /**
 59→     * Writes a v2 SSTable with the given compression codec.
 60→     */
 61→    private Path writeV2SSTable(Path dir, String name, List<Entry> entries,
 62→            CompressionCodec codec) throws IOException {
 63→        Path path = dir.resolve(name);
 64→        try (TrieSSTableWriter w = new TrieSSTableWriter(1L, Level.L0, path,
 65→                n -> new BlockedBloomFilter(n, 0.01), codec)) {
 66→            for (Entry e : entries) {
 67→                w.append(e);
 68→            }
 69→            w.finish();
 70→        }
 71→        return path;
 72→    }
 73→
 74→    private List<Entry> basicEntries() {
 75→        return List.of(
 76→                put("apple", "red", 1),
 77→                put("banana", "yellow", 2),
 78→                del("cherry", 3),
 79→                put("date", "brown", 4),
 80→                put("elderberry", "purple", 5));
 81→    }
 82→
 83→    // ---- v2 with NoneCodec ----
 84→
 85→    @Test
 86→    void testWriteAndReadV2WithNoneCodec(@TempDir Path dir) throws IOException {
 87→        List<Entry> entries = basicEntries();
 88→        Path path = writeV2SSTable(dir, "none.sst", entries, CompressionCodec.none());
 89→
 90→        try (TrieSSTableReader r = TrieSSTableReader.open(path,
 91→                BlockedBloomFilter.deserializer(), null, CompressionCodec.none())) {
 92→            assertEquals(5L, r.metadata().entryCount());
 93→
 94→            // Verify point lookup
 95→            Optional<Entry> result = r.get(seg("apple"));
 96→            assertTrue(result.isPresent());
 97→            assertInstanceOf(Entry.Put.class, result.get());
 98→            assertEquals(-1L, seg("red").mismatch(((Entry.Put) result.get()).value()));
 99→        }
100→    }
101→
102→    // ---- v2 with DeflateCodec ----
103→
104→    @Test
105→    void testWriteAndReadV2WithDeflateCodec(@TempDir Path dir) throws IOException {
106→        List<Entry> entries = basicEntries();
107→        Path path = writeV2SSTable(dir, "deflate.sst", entries, CompressionCodec.deflate());
108→
109→        try (TrieSSTableReader r = TrieSSTableReader.open(path,
110→                BlockedBloomFilter.deserializer(), null,
111→                CompressionCodec.none(), CompressionCodec.deflate())) {
112→            assertEquals(5L, r.metadata().entryCount());
113→
114→            // Verify all entries via full scan
115→            Iterator<Entry> iter = r.scan();
116→            List<Entry> scanned = new ArrayList<>();
117→            while (iter.hasNext()) {
118→                scanned.add(iter.next());
119→            }
120→            assertEquals(5, scanned.size());
121→
122→            // Verify first entry
123→            assertInstanceOf(Entry.Put.class, scanned.get(0));
124→            assertEquals(-1L, seg("apple").mismatch(scanned.get(0).key()));
125→        }
126→    }
127→
128→    // ---- Deflate produces smaller file ----
129→
130→    @Test
131→    void testDeflateProducesSmallerFile(@TempDir Path dir) throws IOException {
132→        // Write many entries with repetitive values to make compression effective
133→        List<Entry> entries = new ArrayList<>();
134→        for (int i = 0; i < 200; i++) {
135→            String key = "key-%05d".formatted(i);
136→            String value = "value-data-repeated-content-for-compression-".repeat(5) + i;
137→            entries.add(put(key, value, i + 1));
138→        }
139→
140→        Path nonePath = writeV2SSTable(dir, "none.sst", entries, CompressionCodec.none());
141→        Path deflatePath = writeV2SSTable(dir, "deflate.sst", entries, CompressionCodec.deflate());
142→
143→        long noneSize = Files.size(nonePath);
144→        long deflateSize = Files.size(deflatePath);
145→        assertTrue(deflateSize < noneSize,
146→                "deflate file (%d) should be smaller than none file (%d)"
147→                        .formatted(deflateSize, noneSize));
148→    }
149→
150→    // ---- Backward compatibility: v2 reader reads v1 file ----
151→
152→    @Test
153→    void testV2ReaderReadsV1File(@TempDir Path dir) throws IOException {
154→        List<Entry> entries = basicEntries();
155→        Path v1Path = writeV1SSTable(dir, "v1.sst", entries);
156→
157→        // v2 reader with codecs should still read v1 files
158→        try (TrieSSTableReader r = TrieSSTableReader.open(v1Path,
159→                BlockedBloomFilter.deserializer(), null,
160→                CompressionCodec.none(), CompressionCodec.deflate())) {
161→            assertEquals(5L, r.metadata().entryCount());
162→
163→            Optional<Entry> result = r.get(seg("banana"));
164→            assertTrue(result.isPresent());
165→            assertInstanceOf(Entry.Put.class, result.get());
166→            assertEquals(-1L, seg("yellow").mismatch(((Entry.Put) result.get()).value()));
167→        }
168→    }
169→
170→    // ---- Point lookup with compression ----
171→
172→    @Test
173→    void testV2PointLookupWithCompression(@TempDir Path dir) throws IOException {
174→        List<Entry> entries = basicEntries();
175→        Path path = writeV2SSTable(dir, "lookup.sst", entries, CompressionCodec.deflate());
176→
177→        try (TrieSSTableReader r = TrieSSTableReader.open(path,
178→                BlockedBloomFilter.deserializer(), null,
179→                CompressionCodec.none(), CompressionCodec.deflate())) {
180→            // Existing key
181→            Optional<Entry> result = r.get(seg("date"));
182→            assertTrue(result.isPresent());
183→            assertEquals(-1L, seg("brown").mismatch(((Entry.Put) result.get()).value()));
184→
185→            // Missing key
186→            assertTrue(r.get(seg("fig")).isEmpty());
187→
188→            // Deleted key
189→            Optional<Entry> deleted = r.get(seg("cherry"));
190→            assertTrue(deleted.isPresent());
191→            assertInstanceOf(Entry.Delete.class, deleted.get());
192→        }
193→    }
194→
195→    // ---- Range scan with compression ----
196→
197→    @Test
198→    void testV2RangeScanWithCompression(@TempDir Path dir) throws IOException {
199→        List<Entry> entries = basicEntries();
200→        Path path = writeV2SSTable(dir, "range.sst", entries, CompressionCodec.deflate());
201→
202→        try (TrieSSTableReader r = TrieSSTableReader.open(path,
203→                BlockedBloomFilter.deserializer(), null,
204→                CompressionCodec.none(), CompressionCodec.deflate())) {
205→            // Range [banana, elderberry) should return banana, cherry, date
206→            Iterator<Entry> iter = r.scan(seg("banana"), seg("elderberry"));
207→            List<Entry> results = new ArrayList<>();
208→            while (iter.hasNext()) {
209→                results.add(iter.next());
210→            }
211→            assertEquals(3, results.size());
212→            assertEquals(-1L, seg("banana").mismatch(results.get(0).key()));
213→            assertEquals(-1L, seg("cherry").mismatch(results.get(1).key()));
214→            assertEquals(-1L, seg("date").mismatch(results.get(2).key()));
215→        }
216→    }
217→
218→    // ---- Full scan with compression ----
219→
220→    @Test
221→    void testV2FullScanWithCompression(@TempDir Path dir) throws IOException {
222→        List<Entry> entries = basicEntries();
223→        Path path = writeV2SSTable(dir, "scan.sst", entries, CompressionCodec.deflate());
224→
225→        try (TrieSSTableReader r = TrieSSTableReader.open(path,
226→                BlockedBloomFilter.deserializer(), null,
227→                CompressionCodec.none(), CompressionCodec.deflate())) {
228→            Iterator<Entry> iter = r.scan();
229→            List<String> keys = new ArrayList<>();
230→            while (iter.hasNext()) {
231→                keys.add(new String(iter.next().key().toArray(java.lang.foreign.ValueLayout.JAVA_BYTE)));
232→            }
233→            assertEquals(List.of("apple", "banana", "cherry", "date", "elderberry"), keys);
234→        }
235→    }
236→
237→    // ---- Incompressible block stored as NONE ----
238→
239→    @Test
240→    void testIncompressibleBlockStoredAsNone(@TempDir Path dir) throws IOException {
241→        // Random data is incompressible — blocks should fall back to NONE codec
242→        Random rng = new Random(42);
243→        List<Entry> entries = new ArrayList<>();
244→        for (int i = 0; i < 50; i++) {
245→            String key = "key-%05d".formatted(i);
246→            byte[] randomValue = new byte[200];
247→            rng.nextBytes(randomValue);
248→            entries.add(new Entry.Put(seg(key),
249→                    MemorySegment.ofArray(randomValue), new SequenceNumber(i + 1)));
250→        }
251→
252→        Path path = writeV2SSTable(dir, "random.sst", entries, CompressionCodec.deflate());
253→
254→        // Should still be readable — incompressible blocks stored as NONE
255→        try (TrieSSTableReader r = TrieSSTableReader.open(path,
256→                BlockedBloomFilter.deserializer(), null,
257→                CompressionCodec.none(), CompressionCodec.deflate())) {
258→            assertEquals(50, r.metadata().entryCount());
259→            Iterator<Entry> iter = r.scan();
260→            int count = 0;
261→            while (iter.hasNext()) {
262→                iter.next();
263→                count++;
264→            }
265→            assertEquals(50, count);
266→        }
267→    }
268→
269→    // ---- Unknown codec ID → IOException ----
270→
271→    @Test
272→    void testUnknownCodecIdThrowsIOException(@TempDir Path dir) throws IOException {
273→        List<Entry> entries = basicEntries();
274→        // Write with deflate codec
275→        Path path = writeV2SSTable(dir, "deflate.sst", entries, CompressionCodec.deflate());
276→
277→        // Open with only NONE codec — deflate blocks should trigger IOException
278→        assertThrows(IOException.class, () -> {
279→            try (TrieSSTableReader r = TrieSSTableReader.open(path,
280→                    BlockedBloomFilter.deserializer(), null, CompressionCodec.none())) {
281→                // Force reading — might be lazy
282→                r.scan();
283→            }
284→        });
285→    }
286→
287→    // ---- Multiple blocks with compression ----
288→
289→    @Test
290→    void testMultipleBlocksWithCompression(@TempDir Path dir) throws IOException {
291→        // Write enough entries to span multiple 4KB blocks
292→        List<Entry> entries = new ArrayList<>();
293→        for (int i = 0; i < 500; i++) {
294→            String key = "key-%06d".formatted(i);
295→            String value = "value-content-for-block-spanning-test-%06d".formatted(i);
296→            entries.add(put(key, value, i + 1));
297→        }
298→
299→        Path path = writeV2SSTable(dir, "multiblock.sst", entries, CompressionCodec.deflate());
300→
301→        try (TrieSSTableReader r = TrieSSTableReader.open(path,
302→                BlockedBloomFilter.deserializer(), null,
303→                CompressionCodec.none(), CompressionCodec.deflate())) {
304→            assertEquals(500, r.metadata().entryCount());
305→
306→            // Verify scan returns all entries in order
307→            Iterator<Entry> iter = r.scan();
308→            int count = 0;
309→            String prevKey = "";
310→            while (iter.hasNext()) {
311→                Entry e = iter.next();
312→                String key = new String(
313→                        e.key().toArray(java.lang.foreign.ValueLayout.JAVA_BYTE));
314→                assertTrue(key.compareTo(prevKey) > 0,
315→                        "keys must be ascending: '%s' after '%s'".formatted(key, prevKey));
316→                prevKey = key;
317→                count++;
318→            }
319→            assertEquals(500, count);
320→
321→            // Verify point lookups on entries from different blocks
322→            assertTrue(r.get(seg("key-000000")).isPresent());
323→            assertTrue(r.get(seg("key-000250")).isPresent());
324→            assertTrue(r.get(seg("key-000499")).isPresent());
325→            assertTrue(r.get(seg("key-999999")).isEmpty());
326→        }
327→    }
