 55→    // Data block accumulation
 56→    private DataBlock currentBlock = new DataBlock();
 57→    private long writePosition = 0L;
 58→
 59→    // v1: parallel lists of keys (raw byte[]) + absolute file offsets
 60→    // v2: parallel lists of keys + packed (blockIndex << 32 | intraBlockOffset)
 61→    private final List<byte[]> indexKeys = new ArrayList<>();
 62→    private final List<Long> indexOffsets = new ArrayList<>();
