112→    /**
113→     * Creates a v2 writer with per-block compression using the given codec.
114→     *
115→     * <p>
116→     * Pass {@code null} for the codec to produce a v1 (uncompressed) file.
117→     *
118→     * @param id unique SSTable identifier
119→     * @param level LSM level for this SSTable
120→     * @param outputPath path to the output file; must not exist
121→     * @param bloomFactory factory used to create the bloom filter; must not be null
122→     * @param codec compression codec, or null for v1 format
123→     * @throws IOException if the file cannot be opened
124→     */
125→    public TrieSSTableWriter(long id, Level level, Path outputPath,
126→            BloomFilter.Factory bloomFactory, CompressionCodec codec) throws IOException {
127→        Objects.requireNonNull(level, "level must not be null");
128→        Objects.requireNonNull(outputPath, "outputPath must not be null");
129→        Objects.requireNonNull(bloomFactory, "bloomFactory must not be null");
130→        this.id = id;
131→        this.level = level;
132→        this.outputPath = outputPath;
133→        this.bloomFactory = bloomFactory;
134→        this.codec = codec;
135→        this.channel = Files.newByteChannel(outputPath, StandardOpenOption.CREATE_NEW,
136→                StandardOpenOption.WRITE);
137→    }
138→
139→    @Override
140→    public void append(Entry entry) throws IOException {
141→        Objects.requireNonNull(entry, "entry must not be null");
142→        if (state != State.OPEN) {
143→            throw new IllegalStateException("writer is not open (state=" + state + ")");
144→        }
145→
146→        byte[] keyBytes = entry.key().toArray(ValueLayout.JAVA_BYTE);
147→
148→        // Enforce strictly ascending key order
149→        if (lastKeyBytes != null) {
150→            int cmp = compareUnsigned(keyBytes, lastKeyBytes);
151→            if (cmp <= 0) {
152→                throw new IllegalArgumentException(
153→                        "keys must be strictly ascending; got key not greater than previous key");
154→            }
155→        }
156→
157→        // Encode using the already-extracted key bytes to avoid a redundant toArray
158→        byte[] encoded = EntryCodec.encode(entry, keyBytes);
159→
160→        if (codec != null) {
161→            // v2: store (blockIndex, intraBlockOffset) packed into a long
162→            int intraBlockOffset = currentBlock.byteSize();
163→            long packed = ((long) blockCount << 32) | (intraBlockOffset & 0xFFFFFFFFL);
164→            indexKeys.add(keyBytes);
165→            indexOffsets.add(packed);
166→        } else {
167→            // v1: store absolute file offset
168→            long entryAbsOffset = writePosition + currentBlock.byteSize();
169→            indexKeys.add(keyBytes);
170→            indexOffsets.add(entryAbsOffset);
171→        }
172→
173→        currentBlock.add(encoded);
174→        approximateSizeBytes += encoded.length;
175→
176→        // Update stats — reuse keyBytes; clone only for smallest (first entry)
177→        SequenceNumber seq = entry.sequenceNumber();
178→        if (smallestKey == null)
179→            smallestKey = MemorySegment.ofArray(keyBytes.clone());
180→        largestKey = MemorySegment.ofArray(keyBytes);
181→
182→        if (minSequence == null || seq.compareTo(minSequence) < 0)
183→            minSequence = seq;
184→        if (maxSequence == null || seq.compareTo(maxSequence) > 0)
185→            maxSequence = seq;
186→
187→        lastKeyBytes = keyBytes;
188→        entryCount++;
189→
190→        // Flush block if it exceeds the target size
191→        if (currentBlock.byteSize() >= SSTableFormat.DEFAULT_BLOCK_SIZE) {
192→            flushCurrentBlock();
193→        }
194→    }
195→
196→    private void flushCurrentBlock() throws IOException {
197→        if (currentBlock.count() == 0)
198→            return;
199→        byte[] blockBytes = currentBlock.serialize();
200→
201→        if (codec != null) {
202→            // v2: compress the block
203→            byte[] compressed = codec.compress(blockBytes, 0, blockBytes.length);
204→            byte actualCodecId;
205→            byte[] dataToWrite;
206→            if (compressed.length >= blockBytes.length) {
207→                // Incompressible — store raw with NONE codec ID
208→                dataToWrite = blockBytes;
209→                actualCodecId = CompressionCodec.none().codecId();
210→            } else {
211→                dataToWrite = compressed;
212→                actualCodecId = codec.codecId();
213→            }
214→            compressionMapEntries.add(new CompressionMap.Entry(
215→                    writePosition, dataToWrite.length, blockBytes.length, actualCodecId));
216→            writeBytes(dataToWrite);
217→        } else {
218→            // v1: write raw block
219→            writeBytes(blockBytes);
220→        }
221→        blockCount++;
222→        currentBlock = new DataBlock();
223→    }
224→
225→    private void writeBytes(byte[] bytes) throws IOException {
226→        ByteBuffer buf = ByteBuffer.wrap(bytes);
227→        while (buf.hasRemaining()) {
228→            channel.write(buf);
229→        }
230→        writePosition += bytes.length;
231→    }
