259→    private static boolean inRange(byte[] key, byte[] fromKey, byte[] toKey) {
260→        if (fromKey != null && compareUnsigned(key, fromKey) < 0)
261→            return false;
262→        if (toKey != null && compareUnsigned(key, toKey) >= 0)
263→            return false;
264→        return true;
265→    }
