 87→     * Creates a v1 writer (no compression) with a {@link BlockedBloomFilter} at 1% FPR.
 88→     *
 89→     * @param id unique SSTable identifier
 90→     * @param level LSM level for this SSTable
 91→     * @param outputPath path to the output file; must not exist
 92→     * @throws IOException if the file cannot be opened
 93→     */
 94→    public TrieSSTableWriter(long id, Level level, Path outputPath) throws IOException {
 95→        this(id, level, outputPath, n -> new BlockedBloomFilter(n, 0.01), null);
 96→    }
 97→
 98→    /**
 99→     * Creates a v1 writer (no compression) with a custom bloom filter factory.
100→     *
101→     * @param id unique SSTable identifier
102→     * @param level LSM level for this SSTable
103→     * @param outputPath path to the output file; must not exist
104→     * @param bloomFactory factory used to create the bloom filter; must not be null
105→     * @throws IOException if the file cannot be opened
106→     */
107→    public TrieSSTableWriter(long id, Level level, Path outputPath,
108→            BloomFilter.Factory bloomFactory) throws IOException {
109→        this(id, level, outputPath, bloomFactory, null);
110→    }
