139→    @Override
140→    public void append(Entry entry) throws IOException {
141→        Objects.requireNonNull(entry, "entry must not be null");
142→        if (state != State.OPEN) {
143→            throw new IllegalStateException("writer is not open (state=" + state + ")");
144→        }
145→
146→        byte[] keyBytes = entry.key().toArray(ValueLayout.JAVA_BYTE);
147→
148→        // Enforce strictly ascending key order
149→        if (lastKeyBytes != null) {
150→            int cmp = compareUnsigned(keyBytes, lastKeyBytes);
151→            if (cmp <= 0) {
152→                throw new IllegalArgumentException(
153→                        "keys must be strictly ascending; got key not greater than previous key");
154→            }
155→        }
156→
157→        // Encode using the already-extracted key bytes to avoid a redundant toArray
158→        byte[] encoded = EntryCodec.encode(entry, keyBytes);
159→
160→        if (codec != null) {
161→            // v2: store (blockIndex, intraBlockOffset) packed into a long
162→            int intraBlockOffset = currentBlock.byteSize();
163→            long packed = ((long) blockCount << 32) | (intraBlockOffset & 0xFFFFFFFFL);
164→            indexKeys.add(keyBytes);
165→            indexOffsets.add(packed);
166→        } else {
167→            // v1: store absolute file offset
168→            long entryAbsOffset = writePosition + currentBlock.byteSize();
169→            indexKeys.add(keyBytes);
170→            indexOffsets.add(entryAbsOffset);
171→        }
172→
173→        currentBlock.add(encoded);
174→        approximateSizeBytes += encoded.length;
175→
176→        // Update stats — reuse keyBytes; clone only for smallest (first entry)
177→        SequenceNumber seq = entry.sequenceNumber();
178→        if (smallestKey == null)
179→            smallestKey = MemorySegment.ofArray(keyBytes.clone());
180→        largestKey = MemorySegment.ofArray(keyBytes);
181→
182→        if (minSequence == null || seq.compareTo(minSequence) < 0)
183→            minSequence = seq;
184→        if (maxSequence == null || seq.compareTo(maxSequence) > 0)
185→            maxSequence = seq;
186→
187→        lastKeyBytes = keyBytes;
188→        entryCount++;
189→
190→        // Flush block if it exceeds the target size
191→        if (currentBlock.byteSize() >= SSTableFormat.DEFAULT_BLOCK_SIZE) {
192→            flushCurrentBlock();
193→        }
194→    }
195→
196→    private void flushCurrentBlock() throws IOException {
197→        if (currentBlock.count() == 0)
198→            return;
199→        byte[] blockBytes = currentBlock.serialize();
200→
201→        if (codec != null) {
202→            // v2: compress the block
203→            byte[] compressed = codec.compress(blockBytes, 0, blockBytes.length);
204→            byte actualCodecId;
205→            byte[] dataToWrite;
206→            if (compressed.length >= blockBytes.length) {
207→                // Incompressible — store raw with NONE codec ID
208→                dataToWrite = blockBytes;
209→                actualCodecId = CompressionCodec.none().codecId();
210→            } else {
211→                dataToWrite = compressed;
212→                actualCodecId = codec.codecId();
213→            }
214→            compressionMapEntries.add(new CompressionMap.Entry(
215→                    writePosition, dataToWrite.length, blockBytes.length, actualCodecId));
216→            writeBytes(dataToWrite);
217→        } else {
218→            // v1: write raw block
219→            writeBytes(blockBytes);
220→        }
221→        blockCount++;
222→        currentBlock = new DataBlock();
223→    }
224→
225→    private void writeBytes(byte[] bytes) throws IOException {
226→        ByteBuffer buf = ByteBuffer.wrap(bytes);
227→        while (buf.hasRemaining()) {
228→            channel.write(buf);
229→        }
230→        writePosition += bytes.length;
231→    }
232→
233→    @Override
234→    public SSTableMetadata finish() throws IOException {
235→        if (state != State.OPEN) {
236→            throw new IllegalStateException("finish() already called or writer is closed");
237→        }
238→        if (entryCount == 0) {
239→            throw new IllegalStateException("cannot finish an empty SSTable");
240→        }
241→
242→        // Flush remaining block
243→        flushCurrentBlock();
244→
245→        // Build bloom filter
246→        bloomFilter = bloomFactory.create((int) Math.max(1, entryCount));
247→        for (byte[] key : indexKeys) {
248→            bloomFilter.add(MemorySegment.ofArray(key));
249→        }
250→
251→        if (codec != null) {
252→            // v2 layout: [data blocks][compression map][key index][bloom filter][footer 64]
253→            long mapOffset = writePosition;
254→            CompressionMap compressionMap = new CompressionMap(compressionMapEntries);
255→            writeBytes(compressionMap.serialize());
256→            long mapLength = writePosition - mapOffset;
257→
258→            long indexOffset = writePosition;
259→            writeKeyIndexV2();
260→            long indexLength = writePosition - indexOffset;
261→
262→            long filterOffset = writePosition;
263→            MemorySegment filterBytes = bloomFilter.serialize();
264→            byte[] filterArray = filterBytes.toArray(ValueLayout.JAVA_BYTE);
265→            writeBytes(filterArray);
266→            long filterLength = writePosition - filterOffset;
267→
268→            writeFooterV2(mapOffset, mapLength, indexOffset, indexLength, filterOffset,
269→                    filterLength);
270→        } else {
271→            // v1 layout: [data blocks][key index][bloom filter][footer 48]
272→            long indexOffset = writePosition;
273→            writeKeyIndexV1();
274→            long indexLength = writePosition - indexOffset;
275→
276→            long filterOffset = writePosition;
277→            MemorySegment filterBytes = bloomFilter.serialize();
278→            byte[] filterArray = filterBytes.toArray(ValueLayout.JAVA_BYTE);
279→            writeBytes(filterArray);
280→            long filterLength = writePosition - filterOffset;
281→
282→            writeFooterV1(indexOffset, indexLength, filterOffset, filterLength);
283→        }
284→
285→        // fsync if supported (e.g., local FileChannel; skipped for object-storage channels)
286→        if (channel instanceof FileChannel fc)
287→            fc.force(true);
288→
289→        long sizeBytes = writePosition;
290→
291→        state = State.FINISHED;
292→
293→        return new SSTableMetadata(id, outputPath, level, smallestKey, largestKey, minSequence,
294→                maxSequence, sizeBytes, entryCount);
295→    }
296→
297→    /** Writes v1 key index: [numKeys(4)][per key: keyLen(4) + key + fileOffset(8)]. */
298→    private void writeKeyIndexV1() throws IOException {
299→        int numKeys = indexKeys.size();
300→        int indexSize = 4;
301→        for (byte[] k : indexKeys) {
302→            indexSize += 4 + k.length + 8;
303→        }
304→        byte[] buf = new byte[indexSize];
305→        int off = 0;
306→        off = writeInt(buf, off, numKeys);
307→        for (int i = 0; i < numKeys; i++) {
308→            byte[] keyBytes = indexKeys.get(i);
309→            off = writeInt(buf, off, keyBytes.length);
310→            System.arraycopy(keyBytes, 0, buf, off, keyBytes.length);
311→            off += keyBytes.length;
312→            off = writeLong(buf, off, indexOffsets.get(i));
313→        }
314→        writeBytes(buf);
315→    }
316→
317→    /** Writes v2 key index: [numKeys(4)][per key: keyLen(4) + key + blockIndex(4) + intraOff(4)]. */
318→    private void writeKeyIndexV2() throws IOException {
319→        int numKeys = indexKeys.size();
320→        int indexSize = 4;
321→        for (byte[] k : indexKeys) {
322→            indexSize += 4 + k.length + 4 + 4;
323→        }
324→        byte[] buf = new byte[indexSize];
325→        int off = 0;
326→        off = writeInt(buf, off, numKeys);
327→        for (int i = 0; i < numKeys; i++) {
328→            byte[] keyBytes = indexKeys.get(i);
329→            off = writeInt(buf, off, keyBytes.length);
330→            System.arraycopy(keyBytes, 0, buf, off, keyBytes.length);
331→            off += keyBytes.length;
332→            long packed = indexOffsets.get(i);
333→            int blockIndex = (int) (packed >>> 32);
334→            int intraBlockOffset = (int) packed;
335→            off = writeInt(buf, off, blockIndex);
336→            off = writeInt(buf, off, intraBlockOffset);
337→        }
338→        writeBytes(buf);
339→    }
340→
341→    private void writeFooterV1(long idxOffset, long idxLength, long fltOffset, long fltLength)
342→            throws IOException {
343→        byte[] buf = new byte[SSTableFormat.FOOTER_SIZE];
344→        int off = 0;
345→        off = writeLong(buf, off, idxOffset);
346→        off = writeLong(buf, off, idxLength);
347→        off = writeLong(buf, off, fltOffset);
348→        off = writeLong(buf, off, fltLength);
349→        off = writeLong(buf, off, entryCount);
350→        writeLong(buf, off, SSTableFormat.MAGIC);
351→        writeBytes(buf);
352→    }
353→
354→    private void writeFooterV2(long mapOffset, long mapLength, long idxOffset, long idxLength,
355→            long fltOffset, long fltLength) throws IOException {
356→        byte[] buf = new byte[SSTableFormat.FOOTER_SIZE_V2];
357→        int off = 0;
358→        off = writeLong(buf, off, mapOffset);
359→        off = writeLong(buf, off, mapLength);
360→        off = writeLong(buf, off, idxOffset);
361→        off = writeLong(buf, off, idxLength);
362→        off = writeLong(buf, off, fltOffset);
363→        off = writeLong(buf, off, fltLength);
364→        off = writeLong(buf, off, entryCount);
365→        writeLong(buf, off, SSTableFormat.MAGIC_V2);
366→        writeBytes(buf);
367→    }
368→
369→    private static int writeInt(byte[] buf, int off, int v) {
370→        buf[off++] = (byte) (v >>> 24);
371→        buf[off++] = (byte) (v >>> 16);
372→        buf[off++] = (byte) (v >>> 8);
373→        buf[off++] = (byte) v;
374→        return off;
375→    }
376→
377→    private static int writeLong(byte[] buf, int off, long v) {
378→        buf[off++] = (byte) (v >>> 56);
379→        buf[off++] = (byte) (v >>> 48);
380→        buf[off++] = (byte) (v >>> 40);
381→        buf[off++] = (byte) (v >>> 32);
382→        buf[off++] = (byte) (v >>> 24);
383→        buf[off++] = (byte) (v >>> 16);
384→        buf[off++] = (byte) (v >>> 8);
385→        buf[off++] = (byte) v;
386→        return off;
387→    }
388→
389→    @Override
390→    public long entryCount() {
391→        return entryCount;
392→    }
393→
394→    @Override
395→    public long approximateSizeBytes() {
396→        return approximateSizeBytes;
397→    }
398→
399→    @Override
400→    public void close() throws IOException {
401→        if (state == State.CLOSED)
402→            return;
403→        boolean shouldDelete = (state == State.OPEN);
404→        state = State.CLOSED;
405→        IOException channelEx = null;
406→        try {
407→            channel.close();
408→        } catch (IOException e) {
409→            channelEx = e;
410→        } finally {
411→            if (shouldDelete) {
412→                try {
413→                    Files.deleteIfExists(outputPath);
414→                } catch (IOException deleteEx) {
415→                    if (channelEx != null) {
416→                        channelEx.addSuppressed(deleteEx);
417→                    } else {
418→                        channelEx = deleteEx;
419→                    }
420→                }
421→            }
422→        }
423→        if (channelEx != null)
424→            throw channelEx;
425→    }
426→
427→    private static int compareUnsigned(byte[] a, byte[] b) {
428→        int len = Math.min(a.length, b.length);
429→        for (int i = 0; i < len; i++) {
430→            int cmp = Byte.compareUnsigned(a[i], b[i]);
431→            if (cmp != 0)
432→                return cmp;
433→        }
434→        return Integer.compare(a.length, b.length);
435→    }
436→}
