 36→/**
 37→ * Reads an SSTable file written by {@link TrieSSTableWriter}.
 38→ *
 39→ * <p>
 40→ * Supports two file formats:
 41→ * <ul>
 42→ * <li><b>v1</b> — no compression; factory methods without {@link CompressionCodec}</li>
 43→ * <li><b>v2</b> — per-block compression with a compression offset map; factory methods with
 44→ * {@link CompressionCodec} varargs</li>
 45→ * </ul>
 46→ *
 47→ * <p>
 48→ * Two factory method families:
 49→ * <ul>
 50→ * <li>{@link #open} — eager: loads the entire data region into memory on open</li>
 51→ * <li>{@link #openLazy} — lazy: loads only footer, key index, bloom filter; reads data on
 52→ * demand</li>
 53→ * </ul>
 54→ */
 55→public final class TrieSSTableReader implements SSTableReader {
 56→
 57→    private final SSTableMetadata metadata;
 58→    private final KeyIndex keyIndex;
 59→    private final BloomFilter bloomFilter;
 60→    private final long dataEnd; // file offset just past the last data block
 61→
 62→    // Eager mode: all data bytes pre-loaded; lazy mode: null
 63→    private final byte[] eagerData;
 64→
 65→    // Lazy mode: open channel; eager mode: null
 66→    private final SeekableByteChannel lazyChannel;
 67→
 68→    // Optional block cache; null means no caching
 69→    private final BlockCache blockCache;
 70→
 71→    // v2 compression support (null for v1)
 72→    private final CompressionMap compressionMap;
 73→    private final Map<Byte, CompressionCodec> codecMap;
 74→
 75→    private volatile boolean closed = false;
 76→
 77→    private TrieSSTableReader(SSTableMetadata metadata, KeyIndex keyIndex, BloomFilter bloomFilter,
 78→            long dataEnd, byte[] eagerData, SeekableByteChannel lazyChannel,
 79→            BlockCache blockCache, CompressionMap compressionMap,
 80→            Map<Byte, CompressionCodec> codecMap) {
 81→        this.metadata = metadata;
 82→        this.keyIndex = keyIndex;
 83→        this.bloomFilter = bloomFilter;
 84→        this.dataEnd = dataEnd;
 85→        this.eagerData = eagerData;
 86→        this.lazyChannel = lazyChannel;
 87→        this.blockCache = blockCache;
 88→        this.compressionMap = compressionMap;
 89→        this.codecMap = codecMap;
 90→    }
 91→
 92→    // ---- v1 factory methods (no compression) ----
 93→
 94→    public static TrieSSTableReader open(Path path, BloomFilter.Deserializer bloomDeserializer)
 95→            throws IOException {
 96→        return open(path, bloomDeserializer, null);
 97→    }
 98→
 99→    public static TrieSSTableReader open(Path path, BloomFilter.Deserializer bloomDeserializer,
100→            BlockCache blockCache) throws IOException {
101→        Objects.requireNonNull(path, "path must not be null");
102→        Objects.requireNonNull(bloomDeserializer, "bloomDeserializer must not be null");
103→
104→        SeekableByteChannel ch = Files.newByteChannel(path, StandardOpenOption.READ);
105→        try {
106→            long fileSize = ch.size();
107→            Footer footer = readFooterV1(ch, fileSize);
108→            KeyIndex keyIndex = readKeyIndexV1(ch, footer);
109→            BloomFilter bloom = readBloomFilter(ch, footer, bloomDeserializer);
110→            SSTableMetadata meta = buildMetadata(path, fileSize, footer, keyIndex);
111→
112→            // Read entire data region eagerly
113→            int dataLen = (int) footer.idxOffset;
114→            byte[] data = readBytes(ch, 0L, dataLen);
115→            ch.close();
116→
117→            return new TrieSSTableReader(meta, keyIndex, bloom, footer.idxOffset, data, null,
118→                    blockCache, null, null);
119→        } catch (IOException e) {
120→            ch.close();
121→            throw e;
122→        }
123→    }
124→
125→    public static TrieSSTableReader openLazy(Path path, BloomFilter.Deserializer bloomDeserializer)
126→            throws IOException {
127→        return openLazy(path, bloomDeserializer, null);
128→    }
129→
130→    public static TrieSSTableReader openLazy(Path path, BloomFilter.Deserializer bloomDeserializer,
131→            BlockCache blockCache) throws IOException {
132→        Objects.requireNonNull(path, "path must not be null");
133→        Objects.requireNonNull(bloomDeserializer, "bloomDeserializer must not be null");
134→
135→        SeekableByteChannel ch = Files.newByteChannel(path, StandardOpenOption.READ);
136→        try {
137→            long fileSize = ch.size();
138→            Footer footer = readFooterV1(ch, fileSize);
139→            KeyIndex keyIndex = readKeyIndexV1(ch, footer);
140→            BloomFilter bloom = readBloomFilter(ch, footer, bloomDeserializer);
141→            SSTableMetadata meta = buildMetadata(path, fileSize, footer, keyIndex);
142→
143→            return new TrieSSTableReader(meta, keyIndex, bloom, footer.idxOffset, null, ch,
144→                    blockCache, null, null);
145→        } catch (IOException e) {
146→            ch.close();
147→            throw e;
148→        }
149→    }
150→
151→    // ---- v2 factory methods (with compression codec support) ----
152→
153→    /**
154→     * Opens an SSTable file eagerly, with support for both v1 and v2 (compressed) formats.
155→     *
156→     * @param path path to the SSTable file
157→     * @param bloomDeserializer deserializer for the bloom filter
158→     * @param blockCache optional block cache, or null
159→     * @param codecs compression codecs available for decompression; for v2 files, all codec IDs
160→     *            used in the file must be represented
161→     * @return a new reader
162→     * @throws IOException if the file cannot be read or contains an unknown codec ID
163→     */
164→    public static TrieSSTableReader open(Path path, BloomFilter.Deserializer bloomDeserializer,
165→            BlockCache blockCache, CompressionCodec... codecs) throws IOException {
166→        Objects.requireNonNull(path, "path must not be null");
167→        Objects.requireNonNull(bloomDeserializer, "bloomDeserializer must not be null");
168→        Objects.requireNonNull(codecs, "codecs must not be null");
169→
170→        SeekableByteChannel ch = Files.newByteChannel(path, StandardOpenOption.READ);
171→        try {
172→            long fileSize = ch.size();
173→            Footer footer = readFooter(ch, fileSize);
174→
175→            CompressionMap compressionMap = null;
176→            Map<Byte, CompressionCodec> codecMap = null;
177→            long dataEnd;
178→            KeyIndex keyIndex;
179→
180→            if (footer.version == 2) {
181→                byte[] mapBytes = readBytes(ch, footer.mapOffset, (int) footer.mapLength);
182→                compressionMap = CompressionMap.deserialize(mapBytes);
183→                codecMap = buildCodecMap(codecs);
184→                validateCodecMap(compressionMap, codecMap);
185→                keyIndex = readKeyIndexV2(ch, footer);
186→                dataEnd = footer.mapOffset;
187→            } else {
188→                keyIndex = readKeyIndexV1(ch, footer);
189→                dataEnd = footer.idxOffset;
190→            }
191→
192→            BloomFilter bloom = readBloomFilter(ch, footer, bloomDeserializer);
193→            SSTableMetadata meta = buildMetadata(path, fileSize, footer, keyIndex);
194→
195→            int dataLen = (int) dataEnd;
196→            byte[] data = readBytes(ch, 0L, dataLen);
197→            ch.close();
198→
199→            return new TrieSSTableReader(meta, keyIndex, bloom, dataEnd, data, null, blockCache,
200→                    compressionMap, codecMap);
201→        } catch (IOException e) {
202→            ch.close();
203→            throw e;
204→        }
205→    }
206→
207→    /**
208→     * Opens an SSTable file lazily, with support for both v1 and v2 (compressed) formats.
209→     *
210→     * @param path path to the SSTable file
211→     * @param bloomDeserializer deserializer for the bloom filter
212→     * @param blockCache optional block cache, or null
213→     * @param codecs compression codecs available for decompression
214→     * @return a new reader
215→     * @throws IOException if the file cannot be read or contains an unknown codec ID
216→     */
217→    public static TrieSSTableReader openLazy(Path path, BloomFilter.Deserializer bloomDeserializer,
218→            BlockCache blockCache, CompressionCodec... codecs) throws IOException {
219→        Objects.requireNonNull(path, "path must not be null");
220→        Objects.requireNonNull(bloomDeserializer, "bloomDeserializer must not be null");
221→        Objects.requireNonNull(codecs, "codecs must not be null");
222→
223→        SeekableByteChannel ch = Files.newByteChannel(path, StandardOpenOption.READ);
224→        try {
225→            long fileSize = ch.size();
226→            Footer footer = readFooter(ch, fileSize);
227→
228→            CompressionMap compressionMap = null;
229→            Map<Byte, CompressionCodec> codecMap = null;
230→            long dataEnd;
231→            KeyIndex keyIndex;
232→
233→            if (footer.version == 2) {
234→                byte[] mapBytes = readBytes(ch, footer.mapOffset, (int) footer.mapLength);
235→                compressionMap = CompressionMap.deserialize(mapBytes);
236→                codecMap = buildCodecMap(codecs);
237→                validateCodecMap(compressionMap, codecMap);
238→                keyIndex = readKeyIndexV2(ch, footer);
239→                dataEnd = footer.mapOffset;
240→            } else {
241→                keyIndex = readKeyIndexV1(ch, footer);
242→                dataEnd = footer.idxOffset;
243→            }
244→
245→            BloomFilter bloom = readBloomFilter(ch, footer, bloomDeserializer);
246→            SSTableMetadata meta = buildMetadata(path, fileSize, footer, keyIndex);
247→
248→            return new TrieSSTableReader(meta, keyIndex, bloom, dataEnd, null, ch, blockCache,
249→                    compressionMap, codecMap);
250→        } catch (IOException e) {
251→            ch.close();
252→            throw e;
253→        }
254→    }
255→
256→    // ---- SSTableReader interface ----
257→
258→    @Override
259→    public SSTableMetadata metadata() {
260→        return metadata;
261→    }
262→
263→    @Override
264→    public Optional<Entry> get(MemorySegment key) throws IOException {
265→        Objects.requireNonNull(key, "key must not be null");
266→        checkNotClosed();
267→
268→        if (!bloomFilter.mightContain(key)) {
269→            return Optional.empty();
270→        }
271→
272→        Optional<Long> offsetOpt = keyIndex.lookup(key);
273→        if (offsetOpt.isEmpty()) {
274→            return Optional.empty();
275→        }
276→
277→        long offset = offsetOpt.get();
278→
279→        if (compressionMap != null) {
280→            // v2: offset is packed (blockIndex << 32 | intraBlockOffset)
281→            int blockIndex = (int) (offset >>> 32);
282→            int intraBlockOffset = (int) offset;
283→            byte[] decompressedBlock = readAndDecompressBlock(blockIndex);
284→            return Optional.of(EntryCodec.decode(decompressedBlock, intraBlockOffset));
285→        } else {
286→            // v1: offset is absolute file position
287→            byte[] entryBytes = readDataAtV1(offset, SSTableFormat.DEFAULT_BLOCK_SIZE);
288→            return Optional.of(EntryCodec.decode(entryBytes, 0));
289→        }
290→    }
291→
292→    @Override
293→    public Iterator<Entry> scan() throws IOException {
294→        checkNotClosed();
295→        if (compressionMap != null) {
296→            // v2: decompress all blocks and iterate
297→            byte[] allData = decompressAllBlocks();
298→            return new DataRegionIterator(allData, allData.length);
299→        } else {
300→            // v1: iterate raw data region
301→            byte[] data = getAllDataV1();
302→            return new DataRegionIterator(data, dataEnd);
303→        }
304→    }
305→
306→    @Override
307→    public Iterator<Entry> scan(MemorySegment fromKey, MemorySegment toKey) throws IOException {
308→        Objects.requireNonNull(fromKey, "fromKey must not be null");
309→        Objects.requireNonNull(toKey, "toKey must not be null");
310→        checkNotClosed();
311→        return new IndexRangeIterator(keyIndex.rangeIterator(fromKey, toKey));
312→    }
313→
314→    @Override
315→    public void close() throws IOException {
316→        if (closed)
317→            return;
318→        closed = true;
319→        if (lazyChannel != null) {
320→            lazyChannel.close();
321→        }
322→    }
323→
324→    // ---- v2 compression helpers ----
325→
326→    /**
327→     * Reads and decompresses a single block by index using the compression map.
328→     */
329→    private byte[] readAndDecompressBlock(int blockIndex) throws IOException {
330→        assert compressionMap != null : "readAndDecompressBlock called on v1 reader";
331→        assert codecMap != null : "codecMap must not be null for v2";
332→
333→        CompressionMap.Entry mapEntry = compressionMap.entry(blockIndex);
334→
335→        if (blockCache != null) {
336→            Optional<MemorySegment> hit = blockCache.get(metadata.id(), blockIndex);
337→            if (hit.isPresent()) {
338→                return hit.get().toArray(ValueLayout.JAVA_BYTE);
339→            }
340→        }
341→
342→        byte[] compressed;
343→        if (eagerData != null) {
344→            compressed = new byte[mapEntry.compressedSize()];
345→            System.arraycopy(eagerData, (int) mapEntry.blockOffset(), compressed, 0,
346→                    mapEntry.compressedSize());
347→        } else {
348→            compressed = readBytes(lazyChannel, mapEntry.blockOffset(), mapEntry.compressedSize());
349→        }
350→
351→        CompressionCodec codec = codecMap.get(mapEntry.codecId());
352→        assert codec != null : "codec not found for ID 0x%02x".formatted(mapEntry.codecId());
353→        byte[] decompressed = codec.decompress(compressed, 0, compressed.length,
354→                mapEntry.uncompressedSize());
355→
356→        if (blockCache != null) {
357→            blockCache.put(metadata.id(), blockIndex, MemorySegment.ofArray(decompressed));
358→        }
359→
360→        return decompressed;
361→    }
362→
363→    /**
364→     * Decompresses all blocks and concatenates them into a single byte array for full scan.
365→     */
366→    private byte[] decompressAllBlocks() throws IOException {
367→        assert compressionMap != null : "decompressAllBlocks called on v1 reader";
368→        int totalUncompressed = 0;
369→        for (int i = 0; i < compressionMap.blockCount(); i++) {
370→            totalUncompressed += compressionMap.entry(i).uncompressedSize();
371→        }
372→        byte[] result = new byte[totalUncompressed];
373→        int off = 0;
374→        for (int i = 0; i < compressionMap.blockCount(); i++) {
375→            byte[] block = readAndDecompressBlock(i);
376→            System.arraycopy(block, 0, result, off, block.length);
377→            off += block.length;
378→        }
379→        assert off == totalUncompressed : "decompressed size mismatch";
380→        return result;
381→    }
382→
383→    private static Map<Byte, CompressionCodec> buildCodecMap(CompressionCodec... codecs) {
384→        Map<Byte, CompressionCodec> map = new HashMap<>();
385→        for (CompressionCodec codec : codecs) {
386→            map.put(codec.codecId(), codec);
387→        }
388→        return Collections.unmodifiableMap(map);
389→    }
390→
391→    private static void validateCodecMap(CompressionMap compressionMap,
392→            Map<Byte, CompressionCodec> codecMap) throws IOException {
393→        for (int i = 0; i < compressionMap.blockCount(); i++) {
394→            byte codecId = compressionMap.entry(i).codecId();
395→            if (!codecMap.containsKey(codecId)) {
396→                throw new IOException(
397→                        "unknown compression codec ID 0x%02x in block %d; available codecs: %s"
398→                                .formatted(codecId, i, codecMap.keySet()));
399→            }
400→        }
401→    }
402→
403→    // ---- v1 internal helpers ----
404→
405→    private void checkNotClosed() throws IOException {
406→        if (closed)
407→            throw new IllegalStateException("reader is closed");
408→    }
409→
410→    /** Returns the data at {@code fileOffset} (v1 absolute offset), reading at most maxBytes. */
411→    private byte[] readDataAtV1(long fileOffset, int maxBytes) throws IOException {
412→        int len = (int) Math.min(maxBytes, dataEnd - fileOffset);
413→        if (len <= 0)
414→            throw new IOException("file offset out of data range: " + fileOffset);
415→
416→        if (blockCache != null) {
417→            Optional<MemorySegment> hit = blockCache.get(metadata.id(), fileOffset);
418→            if (hit.isPresent()) {
419→                return hit.get().toArray(ValueLayout.JAVA_BYTE);
420→            }
421→        }
422→
423→        byte[] data;
424→        if (eagerData != null) {
425→            data = new byte[len];
426→            System.arraycopy(eagerData, (int) fileOffset, data, 0, len);
427→        } else {
428→            data = readBytes(lazyChannel, fileOffset, len);
429→        }
430→
431→        if (blockCache != null) {
432→            blockCache.put(metadata.id(), fileOffset, MemorySegment.ofArray(data));
433→        }
434→        return data;
435→    }
436→
437→    /** Returns the full data region for v1 full scan. */
438→    private byte[] getAllDataV1() throws IOException {
439→        if (eagerData != null)
440→            return eagerData;
441→        return readBytes(lazyChannel, 0L, (int) dataEnd);
442→    }
443→
444→    // ---- Footer / index / filter loading ----
445→
446→    private record Footer(int version, long mapOffset, long mapLength, long idxOffset,
447→            long idxLength, long fltOffset, long fltLength, long entryCount) {
448→    }
449→
450→    /** Reads a v1-only footer. Throws on v2 magic. */
451→    private static Footer readFooterV1(SeekableByteChannel ch, long fileSize) throws IOException {
452→        if (fileSize < SSTableFormat.FOOTER_SIZE) {
453→            throw new IOException("not a valid SSTable file: too small");
454→        }
455→        byte[] buf = readBytes(ch, fileSize - SSTableFormat.FOOTER_SIZE, SSTableFormat.FOOTER_SIZE);
456→        long idxOffset = readLong(buf, 0);
457→        long idxLength = readLong(buf, 8);
458→        long fltOffset = readLong(buf, 16);
459→        long fltLength = readLong(buf, 24);
460→        long entryCount = readLong(buf, 32);
461→        long magic = readLong(buf, 40);
462→        if (magic != SSTableFormat.MAGIC) {
463→            throw new IOException("not a valid SSTable file: bad magic " + Long.toHexString(magic));
464→        }
465→        return new Footer(1, 0, 0, idxOffset, idxLength, fltOffset, fltLength, entryCount);
466→    }
467→
468→    /** Reads footer detecting v1 or v2 format from magic bytes. */
469→    private static Footer readFooter(SeekableByteChannel ch, long fileSize) throws IOException {
470→        if (fileSize < SSTableFormat.FOOTER_SIZE) {
471→            throw new IOException("not a valid SSTable file: too small");
472→        }
473→        // Read the last 8 bytes to check magic
474→        byte[] magicBuf = readBytes(ch, fileSize - 8, 8);
475→        long magic = readLong(magicBuf, 0);
476→
477→        if (magic == SSTableFormat.MAGIC_V2) {
478→            if (fileSize < SSTableFormat.FOOTER_SIZE_V2) {
479→                throw new IOException("not a valid v2 SSTable file: too small");
480→            }
481→            byte[] buf = readBytes(ch, fileSize - SSTableFormat.FOOTER_SIZE_V2,
482→                    SSTableFormat.FOOTER_SIZE_V2);
483→            long mapOffset = readLong(buf, 0);
484→            long mapLength = readLong(buf, 8);
485→            long idxOffset = readLong(buf, 16);
486→            long idxLength = readLong(buf, 24);
487→            long fltOffset = readLong(buf, 32);
488→            long fltLength = readLong(buf, 40);
489→            long entryCount = readLong(buf, 48);
490→            return new Footer(2, mapOffset, mapLength, idxOffset, idxLength, fltOffset, fltLength,
491→                    entryCount);
492→        } else if (magic == SSTableFormat.MAGIC) {
493→            byte[] buf = readBytes(ch, fileSize - SSTableFormat.FOOTER_SIZE,
494→                    SSTableFormat.FOOTER_SIZE);
495→            long idxOffset = readLong(buf, 0);
496→            long idxLength = readLong(buf, 8);
497→            long fltOffset = readLong(buf, 16);
498→            long fltLength = readLong(buf, 24);
499→            long entryCount = readLong(buf, 32);
500→            return new Footer(1, 0, 0, idxOffset, idxLength, fltOffset, fltLength, entryCount);
501→        } else {
502→            throw new IOException(
503→                    "not a valid SSTable file: bad magic " + Long.toHexString(magic));
504→        }
505→    }
506→
507→    /** Reads v1 key index: [numKeys(4)][per key: keyLen(4) + key + fileOffset(8)]. */
508→    private static KeyIndex readKeyIndexV1(SeekableByteChannel ch, Footer footer)
509→            throws IOException {
510→        byte[] buf = readBytes(ch, footer.idxOffset, (int) footer.idxLength);
511→        int numKeys = readInt(buf, 0);
512→        List<MemorySegment> keys = new ArrayList<>(numKeys);
513→        List<Long> offsets = new ArrayList<>(numKeys);
514→        int off = 4;
515→        for (int i = 0; i < numKeys; i++) {
516→            int keyLen = readInt(buf, off);
517→            off += 4;
518→            byte[] keyBytes = new byte[keyLen];
519→            System.arraycopy(buf, off, keyBytes, 0, keyLen);
520→            off += keyLen;
521→            long fileOffset = readLong(buf, off);
522→            off += 8;
523→            keys.add(MemorySegment.ofArray(keyBytes));
524→            offsets.add(fileOffset);
525→        }
526→        return new KeyIndex(keys, offsets);
527→    }
528→
529→    /** Reads v2 key index: [numKeys(4)][per key: keyLen(4) + key + blockIndex(4) + intraOff(4)]. */
530→    private static KeyIndex readKeyIndexV2(SeekableByteChannel ch, Footer footer)
531→            throws IOException {
532→        byte[] buf = readBytes(ch, footer.idxOffset, (int) footer.idxLength);
533→        int numKeys = readInt(buf, 0);
534→        List<MemorySegment> keys = new ArrayList<>(numKeys);
535→        List<Long> offsets = new ArrayList<>(numKeys);
536→        int off = 4;
537→        for (int i = 0; i < numKeys; i++) {
538→            int keyLen = readInt(buf, off);
539→            off += 4;
540→            byte[] keyBytes = new byte[keyLen];
541→            System.arraycopy(buf, off, keyBytes, 0, keyLen);
542→            off += keyLen;
543→            int blockIndex = readInt(buf, off);
544→            off += 4;
545→            int intraBlockOffset = readInt(buf, off);
546→            off += 4;
547→            // Pack into a single long, same encoding as the writer
548→            long packed = ((long) blockIndex << 32) | (intraBlockOffset & 0xFFFFFFFFL);
549→            keys.add(MemorySegment.ofArray(keyBytes));
550→            offsets.add(packed);
551→        }
552→        return new KeyIndex(keys, offsets);
553→    }
554→
555→    private static BloomFilter readBloomFilter(SeekableByteChannel ch, Footer footer,
556→            BloomFilter.Deserializer deserializer) throws IOException {
557→        byte[] buf = readBytes(ch, footer.fltOffset, (int) footer.fltLength);
558→        // Use an Arena-allocated segment to satisfy the alignment constraints of the deserializer
559→        // (BlockedBloomFilter uses JAVA_INT/JAVA_LONG without withByteAlignment(1)).
560→        try (Arena arena = Arena.ofShared()) {
561→            MemorySegment seg = arena.allocate(buf.length, 8);
562→            MemorySegment.copy(MemorySegment.ofArray(buf), 0, seg, 0, buf.length);
563→            return deserializer.deserialize(seg);
564→        }
565→    }
566→
567→    private static SSTableMetadata buildMetadata(Path path, long fileSize, Footer footer,
568→            KeyIndex keyIndex) {
569→        MemorySegment smallestKey = null;
570→        MemorySegment largestKey = null;
571→        Iterator<KeyIndex.Entry> it = keyIndex.iterator();
572→        while (it.hasNext()) {
573→            KeyIndex.Entry e = it.next();
574→            if (smallestKey == null)
575→                smallestKey = e.key();
576→            largestKey = e.key();
577→        }
578→        assert smallestKey != null : "key index must not be empty when building metadata";
579→        return new SSTableMetadata(0L, path, Level.L0, smallestKey, largestKey, SequenceNumber.ZERO,
580→                SequenceNumber.ZERO, fileSize, footer.entryCount);
581→    }
582→
583→    // ---- Low-level I/O ----
584→
585→    private static byte[] readBytes(SeekableByteChannel ch, long offset, int length)
586→            throws IOException {
587→        if (length == 0)
588→            return new byte[0];
589→        ByteBuffer buf = ByteBuffer.allocate(length);
590→        ch.position(offset);
591→        while (buf.hasRemaining()) {
592→            int read = ch.read(buf);
593→            if (read < 0)
594→                throw new IOException("unexpected EOF at offset " + (offset + buf.position()));
595→        }
596→        return buf.array();
597→    }
598→
599→    private static int readInt(byte[] buf, int off) {
600→        return ((buf[off] & 0xFF) << 24) | ((buf[off + 1] & 0xFF) << 16)
601→                | ((buf[off + 2] & 0xFF) << 8) | (buf[off + 3] & 0xFF);
602→    }
603→
604→    private static long readLong(byte[] buf, int off) {
605→        return ((long) (buf[off] & 0xFF) << 56) | ((long) (buf[off + 1] & 0xFF) << 48)
606→                | ((long) (buf[off + 2] & 0xFF) << 40) | ((long) (buf[off + 3] & 0xFF) << 32)
607→                | ((long) (buf[off + 4] & 0xFF) << 24) | ((long) (buf[off + 5] & 0xFF) << 16)
608→                | ((long) (buf[off + 6] & 0xFF) << 8) | (long) (buf[off + 7] & 0xFF);
609→    }
610→
611→    // ---- Iterators ----
612→
613→    /**
614→     * Iterates entries by parsing the raw data region linearly (block by block). Parses: [int
615→     * count][entry...][int count][entry...]... until offset reaches dataEnd.
616→     */
617→    private static final class DataRegionIterator implements Iterator<Entry> {
618→        private final byte[] data;
619→        private final long dataEnd;
620→        private int offset = 0;
621→        private List<Entry> blockEntries = new ArrayList<>();
622→        private int entryIdx = 0;
623→        private Entry next;
624→
625→        DataRegionIterator(byte[] data, long dataEnd) {
626→            this.data = data;
627→            this.dataEnd = dataEnd;
628→            advance();
629→        }
630→
631→        private void advance() {
632→            next = null;
633→            while (true) {
634→                if (entryIdx < blockEntries.size()) {
635→                    next = blockEntries.get(entryIdx++);
636→                    return;
637→                }
638→                if (offset >= dataEnd)
639→                    return;
640→                // Parse next block
641→                int count = readInt(data, offset);
642→                offset += 4;
643→                blockEntries = new ArrayList<>(count);
644→                for (int i = 0; i < count; i++) {
645→                    Entry e = EntryCodec.decode(data, offset);
646→                    blockEntries.add(e);
647→                    offset += EntryCodec.encodedSize(e);
648→                }
649→                entryIdx = 0;
650→            }
651→        }
652→
653→        @Override
654→        public boolean hasNext() {
655→            return next != null;
656→        }
657→
658→        @Override
659→        public Entry next() {
660→            if (next == null)
661→                throw new NoSuchElementException();
662→            Entry result = next;
663→            advance();
664→            return result;
665→        }
666→
667→        private static int readInt(byte[] buf, int off) {
668→            return ((buf[off] & 0xFF) << 24) | ((buf[off + 1] & 0xFF) << 16)
669→                    | ((buf[off + 2] & 0xFF) << 8) | (buf[off + 3] & 0xFF);
670→        }
671→    }
672→
673→    /**
674→     * Iterates entries via key index range results, reading each entry at its offset. Handles both
675→     * v1 (absolute file offset) and v2 (packed blockIndex + intraBlockOffset) formats.
676→     */
677→    private final class IndexRangeIterator implements Iterator<Entry> {
678→        private final Iterator<KeyIndex.Entry> indexIter;
679→        private Entry next;
680→
681→        IndexRangeIterator(Iterator<KeyIndex.Entry> indexIter) {
682→            this.indexIter = indexIter;
683→            advance();
684→        }
685→
686→        private void advance() {
687→            next = null;
688→            if (!indexIter.hasNext())
689→                return;
690→            KeyIndex.Entry ie = indexIter.next();
691→            try {
692→                if (compressionMap != null) {
693→                    // v2: unpack (blockIndex, intraBlockOffset) and decompress
694→                    long packed = ie.fileOffset();
695→                    int blockIndex = (int) (packed >>> 32);
696→                    int intraBlockOffset = (int) packed;
697→                    byte[] block = readAndDecompressBlock(blockIndex);
698→                    next = EntryCodec.decode(block, intraBlockOffset);
699→                } else {
700→                    // v1: read at absolute file offset
701→                    byte[] buf = readDataAtV1(ie.fileOffset(), SSTableFormat.DEFAULT_BLOCK_SIZE);
702→                    next = EntryCodec.decode(buf, 0);
703→                }
704→            } catch (IOException e) {
705→                throw new UncheckedIOException(e);
706→            }
707→        }
708→
709→        @Override
710→        public boolean hasNext() {
711→            return next != null;
712→        }
713→
714→        @Override
715→        public Entry next() {
716→            if (next == null)
717→                throw new NoSuchElementException();
718→            Entry result = next;
719→            advance();
720→            return result;
721→        }
722→    }
723→}
